// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.util.List;
import java.util.Objects;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import org.eclipse.rdf4j.query.explanation.Explanation;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.eclipse.rdf4j.sail.Sail;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.testsuite.sail.ScopeSafetyStoreTest;
import org.junit.jupiter.api.Test;

/** Runs the shared exact-result scope corpus through the native-capable strategy and its generic fallback. */
class LmdbNativeScopeSafetyTest extends ScopeSafetyStoreTest {
	private static final Pattern NATIVE_INVOCATION = Pattern.compile("nativeInvocationsActual=[1-9][0-9]*");
	private static final Pattern EXECUTION_PATH = Pattern.compile("nativeExecutionPath=[^,) ]+");

	@Override
	protected Sail createSail(Path dataDirectory) {
		LmdbStore store = new LmdbStore(dataDirectory.toFile(),
				new LmdbStoreConfig().setNativeEvaluationEnabled(true));
		assertThat(store.isNativeQueryEngineEnabled()).isEqualTo(storeNativeEnabled());
		return store;
	}

	@Test
	void representativeCorpusQueriesRecordTheirExecutionRoutes() throws Exception {
		SailRepository repository = new SailRepository(createSail(dataDirectory.resolve("route-evidence")));
		try {
			repository.init();
			try (var connection = repository.getConnection();
					InputStream data = resource("scope-safety/data/scope-data.trig")) {
				connection.add(data, "urn:scope-safety:", RDFFormat.TRIG);
			}
			for (String queryPath : List.of("queries/q12.rq", "queries/q37.rq", "queries/q50.rq",
					"adversarial/queries/a06.rq", "adversarial/queries/a09.rq", "adversarial/queries/a10.rq")) {
				String query;
				try (InputStream input = resource("scope-safety/" + queryPath)) {
					query = new String(input.readAllBytes(), StandardCharsets.UTF_8);
				}
				try (var connection = repository.getConnection()) {
					String plan = connection.prepareTupleQuery(query).explain(Explanation.Level.Telemetry).toString();
					Matcher invocation = NATIVE_INVOCATION.matcher(plan);
					Matcher path = EXECUTION_PATH.matcher(plan);
					boolean nativeExecution = invocation.find();
					System.out.println("Scope corpus route " + queryPath + ": "
							+ (nativeExecution ? invocation.group() : "no native invocation") + ", "
							+ (path.find() ? path.group() : "generic evaluation"));
					assertThat(nativeExecution).as("%s execution route:%n%s", queryPath, plan)
							.isEqualTo(storeNativeEnabled());
				}
			}
		} finally {
			repository.shutDown();
		}
	}

	private static boolean storeNativeEnabled() {
		return Boolean.parseBoolean(System.getProperty("rdf4j.lmdb.nativeQueryEngine.enabled", "true"));
	}

	private static InputStream resource(String name) {
		return Objects.requireNonNull(ScopeSafetyStoreTest.class.getClassLoader().getResourceAsStream(name), name);
	}
}
